            let ancestor_is_describe_call = {
                node.syntax()
                    .ancestors()
                    .filter_map(JsCallExpression::cast)
                    .find_map(|call_expression| {
                        let callee = call_expression.callee().ok()?;
                        contains_describe_call(&callee).then_some(true)
                    })
            };
