                    return Some(assertion_call.range());
                }
            } else if ASSERTION_FUNCTION_NAMES.contains(&call_text.text()) {
                return Some(assertion_call.range());
            }
        }

        None
    }

    fn diagnostic(_ctx: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state,
                markup! {
                    "The assertion isn't inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
                },
            )
            .note(markup! {
                "This will result in unexpected behaviours from your test suite."
            })
            .note(markup! {
                "Move the assertion inside a "<Emphasis>"it()"</Emphasis>", "<Emphasis>"test()"</Emphasis>" or "<Emphasis>"Deno.test()"</Emphasis>" function call."
            }),
        )
    }
}

/// Returns the reference identifier of the object of a callee expression.
fn get_callee_object_identifier(callee: &AnyJsExpression) -> Option<JsReferenceIdentifier> {
    match callee {
        AnyJsExpression::JsStaticMemberExpression(node) => {
            let member = node.object().ok()?;
            member.as_js_identifier_expression()?.name().ok()
        }
        AnyJsExpression::JsTemplateExpression(node) => {
            let tag = node.tag()?;
            let tag = tag.as_js_static_member_expression()?;
            let member = tag.object().ok()?;
            member.as_js_identifier_expression()?.name().ok()
        }
        AnyJsExpression::JsIdentifierExpression(node) => node.name().ok(),
        _ => None,
    }
}

/// Checks whether the current function call is:
/// - `describe`
fn contains_describe_call(callee: &AnyJsExpression) -> bool {
    let mut members = CalleeNamesIterator::new(callee.clone());

    if let Some(member) = members.next() {
        return member.text() == "describe";
    }
    false
}

